 @Test void sourceCostsAndOriginalReceiptRemainTraceable(){Map<String,Object> catalog=returns.sources("QM",purchase,"");Map<String,Object> l=((List<Map<String,Object>>)catalog.get("rows")).get(0);assertEquals(10,((Number)l.get("source_quantity")).intValue());assertEquals(new java.math.BigDecimal("2.50"),l.get("purchase_price"));long id=create(3);Map<String,Object>d=returns.detail("QM",id);assertEquals("DRAFT",d.get("state"));assertEquals(10,service.detail("QM","purchase",purchase).get("numberActually"));assertEquals(0L,d.get("posted_quantity"));verify(stock,never()).execute(anyString(),anyString(),anyMap());}
