 @Test void approvalThenVirtualWorkerPostsExactlyOnce(){long id=create(3);returns.approve("QM",id,review(),"reviewer");assertEquals("APPROVING",returns.detail("QM",id).get("state"));returns.process("QM",id);returns.process("QM",id);assertEquals("COMPLETED",returns.detail("QM",id).get("state"));assertEquals(3L,returns.detail("QM",id).get("posted_quantity"));returns.process("QM",id);verify(stock,times(1)).execute(eq("QM"),eq("reserve"),anyMap());verify(stock,times(1)).execute(eq("QM"),eq("post"),anyMap());assertEquals(10,service.detail("QM","purchase",purchase).get("numberActually"));}
 @Test void stockFailureRetainsApprovedSourceAndRetryUsesOriginalDocument(){long id=create(3);returns.approve("QM",id,review(),"reviewer");when(stock.execute(eq("QM"),eq("reserve"),anyMap())).thenReturn(R.fail("库存来源已被其他业务占用"));returns.process("QM",id);assertEquals("APPROVING",returns.detail("QM",id).get("state"));assertTrue(returns.detail("QM",id).get("last_error").toString().contains("占用"));assertEquals(0L,returns.detail("QM",id).get("posted_quantity"));}
 @Test void concurrentApprovalClaimsCannotExceedReceipt() throws Exception {long a=create(7),b=create(7);ExecutorService pool=Executors.newFixedThreadPool(2);try{List<Future<Boolean>> fs=new ArrayList<>();for(long id:Arrays.asList(a,b))fs.add(pool.submit(()->{try{returns.approve("QM",id,review(),"reviewer");return true;}catch(IllegalArgumentException e){return false;}}));int approved=0;for(Future<Boolean> x:fs)if(x.get())approved++;assertEquals(1,approved);}finally{pool.shutdownNow();}}
