 @Test void moneyRecordsAreLimitedByActuallyPostedOriginalCost(){long id=create(3);returns.approve("QM",id,review(),"reviewer");assertThrows(IllegalArgumentException.class,()->returns.funds("QM",id,m("request_key",UUID.randomUUID().toString(),"control_version",2,"funds_state","REFUND","amount","7.50","evidence","退款凭证"),"tester"));returns.process("QM",id);returns.process("QM",id);assertThrows(IllegalArgumentException.class,()->returns.funds("QM",id,m("request_key",UUID.randomUUID().toString(),"control_version",2,"funds_state","REFUND","amount","7.51","evidence","退款凭证"),"tester"));returns.funds("QM",id,m("request_key",UUID.randomUUID().toString(),"control_version",2,"funds_state","CREDIT","amount","7.50","evidence","供应商抵扣凭证"),"tester");assertEquals("CREDIT",returns.detail("QM",id).get("funds_state"));assertThrows(IllegalArgumentException.class,()->returns.funds("QM",id,m("request_key",UUID.randomUUID().toString(),"control_version",2,"funds_state","REFUND","amount","7.50","evidence","重复凭证"),"tester"));}
 @Test void listBatchesWarehouseMetadataAndPreservesOriginalPurchaseNetProjection(){long id=create(3);returns.approve("QM",id,review(),"reviewer");returns.process("QM",id);returns.process("QM",id);Map<String,String> q=new HashMap<>();q.put("purchase_id",String.valueOf(purchase));Map<String,Object> result=returns.list("QM",q);Map<String,Object> row=((List<Map<String,Object>>)result.get("rows")).get(0);assertEquals("虚拟执行，无仓库交互",row.get("warehouseLabel"));assertEquals(3L,((Number)((List<Map<String,Object>>)result.get("returned_by_sku")).get(0).get("quantity")).longValue());}
 @Test void procurementWarehouseLogsHaveDedicatedBusinessAndCurrentProgress(){long id=create(3);returns.approve("QM",id,review(),"reviewer");String sn=returns.detail("QM",id).get("return_sn").toString();db.update("INSERT INTO wms_interaction_log(company_code,connection_id,ticket_sn,task_id,direction,action,result,request_id,request_body) VALUES ('QM',1,?,?,'OUT','PURCHASE_RETURN_QUERY','FAILED','PURCHASE_RETURN_QUERY','')",sn,id);WmsLogQuery logs=new WmsLogQuery();ReflectionTestUtils.setField(logs,"db",context.getBean(WmsStore.class));Map<String,String> q=new HashMap<>();q.put("numberType","DOCUMENT");q.put("number",sn);q.put("allTime","true");Map<String,Object> r=logs.list("QM",q);Map<String,Object> line=((List<Map<String,Object>>)r.get("rows")).get(0);assertEquals("PURCHASE_RETURN",line.get("business_type"));assertEquals("FAILED",line.get("result"));assertEquals("PENDING",line.get("dispatch_state"));}
 Map<String,Object> current(long id){return m("control_version",returns.detail("QM",id).get("control_version"));}
 Map<String,Object> money(long id,String type,String amount){Map<String,Object> c=current(id);c.putAll(m("request_key",UUID.randomUUID().toString(),"funds_state",type,"amount",amount,"evidence","供应商实际凭证"));return c;}
 long full(){long id=create(3);returns.approve("QM",id,review(),"reviewer");returns.process("QM",id);returns.process("QM",id);return id;}
 long partialFinal(){long id=create(5);returns.approve("QM",id,review(),"reviewer");db.update("UPDATE purchase_return SET outbound_mode=1,state='APPROVED',stock_reserved=1,dispatch_state='ACCEPTED' WHERE id=?",id);db.update("UPDATE purchase_return_execution SET outbound_mode=1,stock_ready=1,dispatch_state='ACCEPTED' WHERE return_id=?",id);Map<String,Object> l=((List<Map<String,Object>>)returns.detail("QM",id).get("execution_lines")).get(0);returns.accept("QM",id,m("message_id","SIGNED_FINAL","complete",true,"lines",Collections.singletonList(m("line_key",l.get("id"),"sku_sn",l.get("sku_sn"),"batch_code",l.get("batch_code"),"inventory_type","ZP","quantity",2))),0,true);returns.process("QM",id);return id;}
 Map<String,Object> supplier(long id,String decision,int qty){Map<String,Object>d=returns.detail("QM",id),l=((List<Map<String,Object>>)d.get("lines")).get(0);return m("control_version",d.get("control_version"),"request_key",UUID.randomUUID().toString(),"decision",decision,"evidence","供应商签收或拒收凭证","lines",Collections.singletonList(m("line_id",l.get("id"),"quantity",qty)));}
 PurchaseReturnReclaims reclaims(){PurchaseReturnReclaims r=new PurchaseReturnReclaims();ReflectionTestUtils.setField(r,"carrierBridge",CarrierFixture.bridge());ReflectionTestUtils.setField(r,"db",context.getBean(WmsStore.class));ReflectionTestUtils.setField(r,"connections",context.getBean(WmsConnections.class));ReflectionTestUtils.setField(r,"logs",context.getBean(WmsInteractionLog.class));ReflectionTestUtils.setField(r,"stock",stock);ReflectionTestUtils.setField(r,"protocol",new QimenReclaimProtocol());ReflectionTestUtils.setField(r,"work",mock(PurchaseReturnWork.class));return r;}
 @Test void finalShortHasExplicitProgressAndRemainingWork(){long id=partialFinal();Map<String,Object>d=returns.detail("QM",id);assertEquals("REMAINING",d.get("progress_code"));assertEquals("remaining",d.get("primary_action"));assertEquals(3L,d.get("remaining_hold"));assertEquals(0L,d.get("pending_post_quantity"));Map<String,String> q=new HashMap<>();q.put("quick","REMAINING");assertEquals(1L,returns.list("QM",q).get("total"));}
 @Test void partialStopRetainsActualAndDoesNotLookLikeFullCancellation(){long id=partialFinal();Map<String,Object> cmd=current(id);cmd.put("reason","供应商只退两件");returns.cancel("QM",id,cmd,"tester");returns.process("QM",id);Map<String,Object>d=returns.detail("QM",id);assertEquals("PARTIAL_CLOSED",d.get("progress_code"));assertEquals(2L,d.get("posted_quantity"));assertEquals(3L,d.get("released_quantity"));assertEquals(0L,d.get("remaining_hold"));}
 @Test void continuationKeepsSameBusinessAndExistingHold(){long id=partialFinal();Map<String,Object>cmd=current(id);cmd.putAll(m("request_key",UUID.randomUUID().toString(),"reason","原执行最终短出，继续剩余"));returns.continueRemaining("QM",id,cmd,"tester");returns.process("QM",id);returns.continueRemaining("QM",id,cmd,"tester");assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM purchase_return",Integer.class));assertEquals(2,db.queryForObject("SELECT COUNT(*) FROM purchase_return_execution",Integer.class));assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM purchase_return_continuation",Integer.class));assertEquals("EXISTING",db.queryForObject("SELECT hold_action FROM purchase_return_execution WHERE return_id=? ORDER BY id DESC LIMIT 1",String.class,id));verify(stock,never()).execute(eq("QM"),eq("release"),anyMap());}

 @Test void changedContinuationAndCrossCompanyAreRejected(){long id=partialFinal();Map<String,Object> cmd=current(id);cmd.putAll(m("request_key",UUID.randomUUID().toString(),"reason","继续退剩余"));returns.continueRemaining("QM",id,cmd,"tester");cmd.put("reason","修改同一请求");assertThrows(IllegalArgumentException.class,()->returns.continueRemaining("QM",id,cmd,"tester"));assertThrows(IllegalArgumentException.class,()->returns.continueRemaining("OTHER",id,cmd,"other"));}
 @Test void multipleVouchersAndReversalKeepOriginalRecords(){long id=full();Map<String,Object>a=money(id,"REFUND","3.00");returns.funds("QM",id,a,"tester");returns.funds("QM",id,a,"tester");returns.funds("QM",id,money(id,"CREDIT","2.50"),"tester");assertEquals("MIXED",returns.detail("QM",id).get("funds_state"));assertEquals(new java.math.BigDecimal("2.00"),returns.detail("QM",id).get("funds_remaining"));long original=db.queryForObject("SELECT id FROM purchase_return_fund WHERE return_id=? AND kind='REFUND'",Long.class,id);Map<String,Object> reversal=money(id,"REVERSAL","0");reversal.put("original_id",original);returns.funds("QM",id,reversal,"tester");assertEquals(new java.math.BigDecimal("2.50"),returns.detail("QM",id).get("funds_amount"));assertEquals(3,db.queryForObject("SELECT COUNT(*) FROM purchase_return_fund",Integer.class));Map<String,Object> second=money(id,"REVERSAL","0");second.put("original_id",original);assertThrows(IllegalArgumentException.class,()->returns.funds("QM",id,second,"tester"));}
 @Test void supplierPartialAcceptanceRefusalAndShortageDoNotChangeStock(){long id=full();Map<String,Object> accepted=supplier(id,"ACCEPT",1);returns.supplierReceipt("QM",id,accepted,"tester");returns.supplierReceipt("QM",id,accepted,"tester");returns.supplierReceipt("QM",id,supplier(id,"REFUSE",1),"tester");returns.supplierReceipt("QM",id,supplier(id,"SHORT",1),"tester");Map<String,Object> l=((List<Map<String,Object>>)returns.detail("QM",id).get("lines")).get(0);assertEquals(1L,l.get("supplier_received_quantity"));assertEquals(1L,l.get("supplier_refused_quantity"));assertEquals(3L,l.get("posted_quantity"));assertThrows(IllegalArgumentException.class,()->returns.supplierReceipt("QM",id,supplier(id,"ACCEPT",2),"tester"));verify(stock,never()).execute(eq("QM"),eq("recover"),anyMap());}
 @Test void refusalReclaimRequiresEvidenceAndCreatesNewReceiptSource(){long id=full();PurchaseReturnReclaims r=reclaims();Map<String,Object> doc=returns.detail("QM",id),line=((List<Map<String,Object>>)doc.get("lines")).get(0);Map<String,Object> cmd=m("request_key",UUID.randomUUID().toString(),"control_version",doc.get("control_version"),"reason","供应商拒收退回本仓","standard_id",1,"carrier_code","SF","waybill","REAL-SUPPLIER-RETURN","lines",Collections.singletonList(m("line_id",line.get("id"),"quantity",1)));assertThrows(IllegalArgumentException.class,()->r.create("QM",id,cmd,"tester"));returns.supplierReceipt("QM",id,supplier(id,"REFUSE",1),"tester");cmd.put("control_version",returns.detail("QM",id).get("control_version"));long reclaim=r.create("QM",id,cmd,"tester");assertEquals(reclaim,r.create("QM",id,cmd,"tester"));r.approve("QM",reclaim,m("control_version",1),"reviewer");r.process("QM",reclaim);r.process("QM",reclaim);assertEquals("COMPLETED",r.detail("QM",reclaim).get("state"));assertEquals(3L,returns.detail("QM",id).get("posted_quantity"));verify(stock,times(1)).execute(eq("QM"),eq("recover"),anyMap());assertTrue(((List<Map<String,Object>>)returns.sources("QM",purchase,"").get("rows")).stream().anyMatch(x->x.get("source_key").toString().startsWith("S")));}

 @Test void realReclaimDispatchSurvivesJsonNumericConnectionSnapshot()throws Exception{
  long id=full();returns.supplierReceipt("QM",id,supplier(id,"REFUSE",1),"tester");com.sun.net.httpserver.HttpServer server=com.sun.net.httpserver.HttpServer.create(new java.net.InetSocketAddress("127.0.0.1",0),0);java.util.concurrent.atomic.AtomicInteger sent=new java.util.concurrent.atomic.AtomicInteger();server.createContext("/qimen",exchange->{java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream();byte[] buffer=new byte[4096];int length;while((length=exchange.getRequestBody().read(buffer))!=-1)bytes.write(buffer,0,length);String body=new String(bytes.toByteArray(),java.nio.charset.StandardCharsets.UTF_8);assertTrue(body.contains("<orderType>QTRK</orderType>"));sent.incrementAndGet();byte[] response="<response><flag>success</flag><code>0</code><entryOrderId>WMS_RECLAIM_1</entryOrderId></response>".getBytes(java.nio.charset.StandardCharsets.UTF_8);exchange.sendResponseHeaders(200,response.length);exchange.getResponseBody().write(response);exchange.close();});server.start();try{
   long connection=context.getBean(WmsConnections.class).save("QM",m("name","TEST收回仓库","provider","QIMEN","api_version","2.0","environment","TEST","endpoint","http://127.0.0.1:"+server.getAddress().getPort()+"/qimen","app_key","APP","customer_id","CUSTOMER","secret","TEST-SECRET","enabled",1));
   db.update("UPDATE wms_simulation_store_info SET inbound_mode=1,connection_id=?,external_owner='OWN',external_warehouse='WH' WHERE company_key='QM' AND wms_simulation_code='V'",connection);
   PurchaseReturnReclaims r=reclaims();Map<String,Object>d=returns.detail("QM",id),l=((List<Map<String,Object>>)d.get("lines")).get(0);long reclaim=r.create("QM",id,m("request_key",UUID.randomUUID().toString(),"control_version",d.get("control_version"),"reason","供应商拒收","standard_id",1,"carrier_code","SF","waybill","BACK1","lines",Collections.singletonList(m("line_id",l.get("id"),"quantity",1))),"tester");r.approve("QM",reclaim,m("control_version",1),"reviewer");r.process("QM",reclaim);assertEquals("ACCEPTED",r.detail("QM",reclaim).get("dispatch_state"));assertEquals("WMS_RECLAIM_1",r.detail("QM",reclaim).get("external_order"));assertEquals(1,sent.get());
  }finally{server.stop(0);}
 }

